require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/ol_schema.php';require_login();require_premium();if(!in_array(user_grade_number(),[10,11],true)){redirect('student/dashboard.php');}ensure_ol_schema();$db=db();$medium=medium_language((string)user()['medium']);
$s=db()->prepare("SELECT s.id,s.name_en,s.name_si,s.name_ta,COUNT(p.id) papers FROM subjects s JOIN ol_papers p ON p.subject_id=s.id AND p.medium=? AND p.status=1 WHERE s.status='active' GROUP BY s.id,s.name_en,s.name_si,s.name_ta ORDER BY s.name_en");$s->bind_param('s',$medium);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$pageTitle='O/L Kuppiya subjects';include __DIR__.'/../includes/header.php';?>
<p><a href="index.php">← O/L Kuppiya</a></p><h1>Choose a subject</h1><div class="grid"><?php foreach($rows as $r):?><a class="card" style="text-decoration:none;color:inherit" href="papers.php?subject_id=<?=(int)$r['id']?>"><h2><?=e(locale_value($r,'name'))?></h2><p class="muted"><?=intval($r['papers'])?> papers available</p></a><?php endforeach;if(!$rows):?><div class="card muted">No papers are available for your medium yet.</div><?php endif;?></div>
